import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; public class Test { public static void main(String[] args) { BCryptPasswordEncoder encoder = new BCryptPasswordEncoder(); String hash = "$2a$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi."; System.out.println("Hash for 'password': " + encoder.matches("password", hash)); System.out.println("Hash for 'Admin@123': " + encoder.matches("Admin@123", hash)); System.out.println("Hash for 'Invest@123': " + encoder.matches("Invest@123", hash)); System.out.println("Hash for 'Viewer@123': " + encoder.matches("Viewer@123", hash)); }}
